<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import PriceExceptionSummary from './PriceExceptionSummary.vue'
import { priceExceptionLabel, type PriceException } from '@/data/priceExceptions'
import { batchItemReviews, batchReviewLabels, approvedBatchSheet, loadBatchSingleRecord, loadBatchSingleOriginal, type BatchSingleDocument } from '@/services/batchSingleQuotation'
import { currentAuthUser, hasPermission } from '@/data/authStore'
import BatchSingleReviewActions from './BatchSingleReviewActions.vue'
import { canViewDomesticFreight, canViewPurchaseCost, canViewPricingFactors } from '@/data/quotationVisibility'
import BatchSingleSheet from './BatchSingleSheet.vue'

const props = defineProps<{ document: BatchSingleDocument }>()
const emit = defineEmits<{ close: []; updated: [document: BatchSingleDocument]; correct: [index: number] }>()
const selected = ref<number[]>([]), statusFilter = ref(''), error = ref(''), refreshing = ref(false), original = ref<BatchSingleDocument>()
const actions = ref<InstanceType<typeof BatchSingleReviewActions>>()
const states = computed(() => batchItemReviews(props.document))
const canReview = computed(() => ['super_admin','finance'].includes(currentAuthUser.value.role) && hasPermission('allRecords'))
const own = computed(() => props.document.review?.claimantAccount === currentAuthUser.value.account && props.document.review.status === 'reviewing')
const canCorrect = computed(() => hasPermission('quote') && (props.document.ownerAccount === currentAuthUser.value.account || currentAuthUser.value.role === 'super_admin') && props.document.review?.status !== 'reviewing')
const exported = computed(() => approvedBatchSheet(props.document))
const pageIndexes = computed(() => visible.value.map(item => props.document.items.indexOf(item)))
const allPage = computed(() => !!pageIndexes.value.length && pageIndexes.value.every(index => selected.value.includes(index)))
const hiddenSelected = computed(() => selected.value.filter(index => !pageIndexes.value.includes(index)).length)
function selectPage() { if (!own.value || actions.value?.busy) return; selected.value = allPage.value ? selected.value.filter(index => !pageIndexes.value.includes(index)) : [...new Set([...selected.value, ...pageIndexes.value])] }
function close() { if (actions.value?.busy || refreshing.value) return; if ((selected.value.length || actions.value?.hasUnsavedChanges) && !window.confirm('还有未提交的选择或审核意见，确定关闭并放弃吗？')) return; emit('close') }
async function reload() { if (!props.document.id || refreshing.value) return; const id = props.document.id, account = currentAuthUser.value.account; refreshing.value = true; error.value = ''; try { const fresh = await loadBatchSingleRecord(id); if (props.document.id === id && account === currentAuthUser.value.account) emit('updated', fresh) } catch (e) { error.value = e instanceof Error ? e.message : '读取失败' } finally { refreshing.value = false } }
async function showOriginal() { tab.value = 'original'; if (!props.document.id) return; const id = props.document.id, account = currentAuthUser.value.account; try { const result = await loadBatchSingleOriginal(id); if (id === props.document.id && account === currentAuthUser.value.account) original.value = result } catch (e) { error.value = e instanceof Error ? e.message : '读取失败' } }
function outcome(value: unknown) { const item = value as { priceException?: PriceException; reviewResult?: string; status?: string; reason?: string; note?: string }; return [batchReviewLabels[item.reviewResult || item.status || ''] || '', item.status === 'rejected' ? priceExceptionLabel(item.priceException?.category) : '', item.reason || item.note || ''].filter(Boolean).join(' · ') }
watch(() => [props.document.id, props.document._reviewVersion, currentAuthUser.value.account], () => { selected.value = []; original.value = undefined })
const query = ref(''), page = ref(0), pageSize = ref(10), tab = ref<'details' | 'sheet' | 'history' | 'original'>('details')
const expanded = ref(new Set(props.document.items.slice(0, 1).map(item => item.input.primarySku)))
const filtered = computed(() => props.document.items.filter(item => item.input.primarySku.toLowerCase().includes(query.value.trim().toLowerCase()) && (!statusFilter.value || (states.value[props.document.items.indexOf(item)]?.reviewResult || states.value[props.document.items.indexOf(item)]?.status) === statusFilter.value)))
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize.value)))
watch(pages, count => { page.value = Math.min(page.value, count - 1) })
const visible = computed(() => filtered.value.slice(page.value * pageSize.value, (page.value + 1) * pageSize.value))
const allExpanded = computed(() => visible.value.length > 0 && visible.value.every(item => expanded.value.has(item.input.primarySku)))
const panel = ref<HTMLElement>(), scroller = ref<HTMLElement>()
const currency = (value?: number | null) => value == null || !Number.isFinite(value) ? '—' : value.toFixed(2)
const date = (value?: string) => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '—'
function toggle(sku: string) { const next = new Set(expanded.value); if (next.has(sku)) next.delete(sku); else next.add(sku); expanded.value = next }
function togglePage() { const next = new Set(expanded.value), collapse = allExpanded.value; visible.value.forEach(item => collapse ? next.delete(item.input.primarySku) : next.add(item.input.primarySku)); expanded.value = next }
watch([query, pageSize, statusFilter], () => { page.value = 0 })
watch(page, () => { scroller.value?.scrollTo?.({ top: 0 }) })
watch(() => props.document.id, () => { query.value = ''; page.value = 0; expanded.value = new Set(); tab.value = 'details' })
let previousFocus: HTMLElement | null = null, previousOverflow = ''
function keydown(event: KeyboardEvent) {
  if (event.key === 'Escape') { event.preventDefault(); close() }
  if (event.key !== 'Tab') return
  const items = [...(panel.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]') || [])].filter(item => item.getClientRects().length)
  if (!items?.length) return
  if (event.shiftKey && document.activeElement === items[0]) { event.preventDefault(); items[items.length - 1]?.focus() }
  else if (!event.shiftKey && document.activeElement === items[items.length - 1]) { event.preventDefault(); items[0]?.focus() }
}
onMounted(() => { previousFocus = document.activeElement as HTMLElement; previousOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; panel.value?.focus() })
onBeforeUnmount(() => { document.body.style.overflow = previousOverflow; previousFocus?.focus() })
</script>

<template>
  <Teleport to="body">
    <div class="batch-detail-mask" @click.self="close()">
      <section ref="panel" class="batch-detail" role="dialog" aria-modal="true" aria-labelledby="batch-detail-title" tabindex="-1" @keydown="keydown">
        <header class="detail-header">
          <div><small>QUOTATION DOCUMENT</small><h2 id="batch-detail-title">{{ document.no }}</h2><p>{{ document.customerName }} · 单品批量 · {{ document.items.length }} 个 SKU · {{ document.sheet.rows.length }} 条渠道</p></div>
          <button class="close" aria-label="关闭批量报价详情" @click="close()">关闭 ×</button>
        </header>
        <div class="snapshot-meta"><span>报价人：{{ document.salespersonName || document.sheet.agent }}</span><span>保存时间：{{ date(document.createdAt) }}</span><span>历史价格快照 · 修订 {{ document.review?.revision || 0 }}</span><b>{{ batchReviewLabels[document.review?.status || 'pending'] }}</b><span v-if="document.review?.claimantName">{{ document.review.claimantName }}审核中</span><button :disabled="refreshing || actions?.busy" @click="reload">刷新状态</button></div>
        <nav class="detail-tabs" aria-label="批量报价详情标签"><button :class="{ active: tab === 'details' }" @click="tab='details'">SKU 与渠道明细</button><button :class="{ active: tab === 'sheet' }" @click="tab='sheet'">客户报价单</button><button :class="{ active: tab === 'history' }" @click="tab='history'">审核与修正记录</button><button :class="{ active: tab === 'original' }" @click="showOriginal">原始报价</button></nav>
        <p v-if="error" role="alert">{{ error }}</p>
        <template v-if="tab==='details'">
          <div class="detail-toolbar"><label>搜索 SKU <input v-model="query" type="search" aria-label="搜索批量明细SKU" placeholder="输入 SKU"></label><select v-model="statusFilter" aria-label="单品逐项审核状态"><option value="">全部审核状态</option><option v-for="value in ['pending','approved','rejected','channel-exempt','logistics-exempt']" :key="value" :value="value">{{ batchReviewLabels[value] }}</option></select><button :disabled="!visible.length" @click="togglePage">{{ allExpanded ? '收起本页渠道' : '展开本页渠道' }}</button><span>点击 SKU 展开渠道，价格按数量分列显示</span></div>
          <div ref="scroller" class="detail-scroll" tabindex="0" aria-label="批量SKU明细滚动区域">
            <table class="sku-detail-table"><thead><tr><th class="sticky-sku"><input v-if="canReview" type="checkbox" :checked="allPage" :disabled="!own || actions?.busy" aria-label="全选本页单品SKU" @change="selectPage"> SKU / 渠道</th><th v-if="canViewPurchaseCost">采购成本 ¥/件</th><th v-if="canViewDomesticFreight">国内运费 ¥/件</th><th v-for="label in document.sheet.quantityLabels" :key="label">{{ label }} · USD</th><th>国家 / 分区</th><th>物流商 / 时效</th><th>审核状态</th></tr></thead>
              <tbody v-for="item in visible" :key="item.input.primarySku" class="sku-group">
                <tr class="sku-summary"><th class="sticky-sku"><input v-if="canReview" v-model="selected" type="checkbox" :value="document.items.indexOf(item)" :disabled="!own || actions?.busy" :aria-label="`选择单品审核 ${item.input.primarySku}`"><button :aria-expanded="expanded.has(item.input.primarySku)" :aria-label="`展开 ${item.input.primarySku} 渠道`" @click="toggle(item.input.primarySku)">{{ expanded.has(item.input.primarySku) ? '▾' : '▸' }} {{ item.input.primarySku }}</button><small>{{ item.sheet.rows.length }} 条渠道</small></th><td v-if="canViewPurchaseCost">{{ currency(item.input.purchaseUnitPriceCny) }}</td><td v-if="canViewDomesticFreight">{{ item.input.domesticFreightPerUnitCny == null ? '未保存' : currency(item.input.domesticFreightPerUnitCny) }}</td><td :colspan="document.sheet.quantityLabels.length + 2">{{ item.input.productSummary || item.input.productCategory || '单品报价' }}<span class="weight" v-if="canViewPricingFactors && item.input.exchangeRate">保存汇率 {{ item.input.exchangeRate }}</span></td><td><b>{{ batchReviewLabels[states[document.items.indexOf(item)]?.reviewResult || states[document.items.indexOf(item)]?.status || 'pending'] }}</b><small v-if="states[document.items.indexOf(item)]?.reviewedBy">{{ states[document.items.indexOf(item)]?.reviewedBy }} · {{ date(states[document.items.indexOf(item)]?.reviewedAt) }}</small><PriceExceptionSummary v-if="states[document.items.indexOf(item)]?.status === 'rejected'" :value="states[document.items.indexOf(item)]?.priceException" /><small>{{ states[document.items.indexOf(item)]?.reason || states[document.items.indexOf(item)]?.note }}</small><button v-if="canCorrect && states[document.items.indexOf(item)]?.status === 'rejected'" @click="emit('correct', document.items.indexOf(item))">修正并重新提交</button></td></tr>
                <template v-if="expanded.has(item.input.primarySku)"><tr v-for="row in item.sheet.rows" :key="row.key"><td class="sticky-sku"><span class="channel-name">{{ row.sourceDescription || row.provider }}</span></td><td v-if="canViewPurchaseCost">—</td><td v-if="canViewDomesticFreight">—</td><td v-for="(price,i) in row.prices" :key="i" class="money">{{ currency(price) }}</td><td>{{ row.country }}<small v-if="row.region">{{ row.region }}</small></td><td>{{ row.provider }}<small>{{ row.shippingTime || '未提供时效' }}</small></td><td></td></tr></template>
              </tbody>
            </table>
            <p v-if="!filtered.length" class="empty">没有匹配的 SKU</p>
          </div>
          <div class="detail-pagination"><span>共 {{ filtered.length }} 个 SKU</span><label>每页 <select v-model.number="pageSize" aria-label="每页SKU数量"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option></select> 个</label><div><button :disabled="page===0" @click="page--">上一页</button><span>{{ page+1 }} / {{ pages }}</span><button :disabled="page+1>=pages" @click="page++">下一页</button></div></div>
        </template>
        <div v-else-if="tab==='sheet'" class="detail-scroll sheet-scroll"><p>仅包含审核通过或免审的SKU（{{ states.filter(item => item.status === 'approved').length }}/{{ document.items.length }}）。</p><BatchSingleSheet v-if="exported.rows.length" :sheet="exported" :photos="document.items[0]?.input.customerQuote?.showPhotos === false ? [] : document.items[0]?.input.customerQuote?.photos" /><p v-else>暂无已审核SKU，审核通过后可生成客户报价单。</p></div>
        <div v-else-if="tab==='original'" class="detail-scroll sheet-scroll"><p>初次保存的报价快照，修正和审核不会覆盖。</p><BatchSingleSheet v-if="original" :sheet="original.sheet" :photos="original.items[0]?.input.customerQuote?.showPhotos === false ? [] : original.items[0]?.input.customerQuote?.photos" read-only /></div>
        <div v-else class="detail-scroll sheet-scroll"><p v-if="!document.review?.history.length">暂无审核与修正记录</p><article v-for="event in [...(document.review?.history || [])].reverse()" :key="event.id" class="history-event"><b>{{ ({claim:'领取审核',cancel:'取消审核',complete:'提交逐项结论',resubmit:'修正重提'} as Record<string,string>)[event.action] || event.action }}</b> · {{ event.actorName }} · {{ date(event.at) }} · 修订 {{ event.revision }}<p>{{ event.note }}</p><div v-for="change in event.items" :key="change.index"><b>{{ change.sku }}</b> · {{ event.action === 'resubmit' ? '已重新查询并生成新修订，原报价保留' : outcome(change.after) }}</div></article></div>
        <footer class="detail-footer"><BatchSingleReviewActions v-show="tab==='details'" ref="actions" :document="document" :selected="selected" :hidden-selected="hiddenSelected" @saved="emit('updated', $event)" @clear="selected=[]" @reload="reload" /><div v-if="!canReview || tab!=='details'" class="view-actions"><span>按保存时的采购、物流和客户价格核对；当前资料变化不会覆盖此报价。</span><button class="primary" @click="tab=tab==='sheet'?'details':'sheet'">{{ tab==='sheet'?'返回 SKU 明细':'查看完整客户报价单' }}</button></div></footer>
      </section>
    </div>
  </Teleport>
</template>

<style scoped>
.batch-detail-mask{position:fixed;inset:0;z-index:1500;background:#10253866;display:flex;justify-content:flex-end}.batch-detail{width:min(1420px,94vw);height:100dvh;display:flex;flex-direction:column;background:#fff;color:#243647;box-shadow:-12px 0 40px #152c4c22;outline:none}.detail-header{padding:20px 24px 12px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-shrink:0}.detail-header small{color:#ec881e;font-size:11px;letter-spacing:1px}.detail-header h2{margin:5px 0;font-size:22px;overflow-wrap:anywhere}.detail-header p{font-size:13px;color:#697c8c;margin:6px 0}.snapshot-meta{display:flex;gap:18px;flex-wrap:wrap;padding:10px 24px;background:#f3f7fa;color:#667987;font-size:12px;flex-shrink:0}.detail-tabs{display:flex;flex-wrap:wrap;gap:22px;padding:0 24px;border-bottom:1px solid #dde5eb;flex-shrink:0}.detail-tabs button{border:0;border-bottom:3px solid transparent;border-radius:0;background:none;padding:13px 0}.detail-tabs button.active{border-color:#ef941e;color:#ae610d;font-weight:700}.detail-toolbar{display:flex;gap:12px;align-items:center;padding:14px 24px;flex-wrap:wrap;flex-shrink:0}.detail-toolbar label{font-size:13px}.detail-toolbar input{margin-left:8px;width:190px;padding:9px;border:1px solid #cdd8e0;border-radius:6px}.detail-toolbar span{font-size:12px;color:#72818e}.detail-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;margin:0 24px;border:1px solid #dee5eb;border-radius:6px}.sku-detail-table{border-collapse:separate;border-spacing:0;min-width:850px;width:100%;font-size:13px;white-space:nowrap}.sku-detail-table th,.sku-detail-table td{padding:12px 14px;border-bottom:1px solid #e3e9ed;text-align:left}.sku-detail-table thead th{position:sticky;top:0;background:#eaf1f8;z-index:3}.sku-detail-table .sticky-sku{position:sticky;left:0;background:#fff;min-width:185px;max-width:300px;z-index:1}.sku-detail-table thead .sticky-sku{z-index:4;background:#eaf1f8}.sku-detail-table small{display:block;font-size:11px;color:#71818d;margin-top:4px}.sku-summary td,.sku-summary .sticky-sku{background:#f6f8fa}.sku-summary button{border:0;background:none;padding:0;color:#223d53;font-weight:700;white-space:nowrap}.money{font-variant-numeric:tabular-nums;font-weight:650;color:#163f58}.weight{margin-left:24px;font-size:12px;color:#788893}.channel-name{display:block;white-space:normal;overflow-wrap:anywhere;font-size:12px}.detail-pagination{padding:12px 24px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;font-size:13px;flex-shrink:0}.detail-pagination div{display:flex;align-items:center;gap:14px;margin-left:auto}.detail-pagination select{padding:7px;border:1px solid #ced9e0;border-radius:5px}.detail-footer{display:flex;flex-direction:column;justify-content:space-between;gap:16px;align-items:center;padding:16px 24px;border-top:1px solid #d9e1e7;background:#fff;box-shadow:0 -5px 18px #16314908;flex-shrink:0}.view-actions{display:flex;justify-content:space-between;gap:12px;align-items:center;width:100%}.history-event{padding:14px;border-bottom:1px solid #dce4ec;font-size:13px}.history-event div{margin-top:8px}.sku-summary td:last-child{white-space:normal;min-width:160px;max-width:260px}.sku-summary small{white-space:normal}.detail-footer span{color:#71818d;font-size:12px;line-height:1.6}.detail-footer button{min-height:44px;white-space:nowrap}.sheet-scroll{padding:12px}.empty{text-align:center;padding:35px;color:#6b7c89}button{padding:9px 13px;background:#fff;border:1px solid #cad6df;border-radius:6px;color:#334d61;cursor:pointer}button:disabled{opacity:.45;cursor:default}button.primary{background:#ff991c;border-color:#ff991c;color:#263440;font-weight:700}@media(max-width:700px){.batch-detail{width:100vw}.detail-header,.snapshot-meta,.detail-toolbar,.detail-pagination,.detail-footer{padding-left:12px;padding-right:12px}.detail-scroll{margin:0 12px}.detail-footer{align-items:flex-end}.detail-footer span{max-width:50%}.detail-tabs{padding:0 12px}}
@media(max-width:700px){.detail-header{padding-top:10px;padding-bottom:6px;gap:6px}.detail-header small{display:none}.detail-header h2{font-size:17px}.detail-header p{font-size:11px;margin:4px 0}.close{white-space:nowrap;padding:7px}.snapshot-meta{padding-top:6px;padding-bottom:6px;gap:6px 10px;font-size:11px;max-height:72px;overflow:auto}.snapshot-meta button{padding:4px 7px}.detail-tabs{gap:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}.detail-tabs button{font-size:11px;padding:9px 3px;line-height:1.4}.detail-toolbar{padding-top:8px;padding-bottom:8px;gap:6px;display:grid;grid-template-columns:1fr 1fr}.detail-toolbar label{grid-column:1/-1;display:flex;align-items:center;font-size:12px}.detail-toolbar input{flex:1;width:0;padding:7px}.detail-toolbar span{display:none}.detail-toolbar select,.detail-toolbar button{font-size:11px;min-height:32px;min-width:0}.detail-pagination{padding-top:6px;padding-bottom:6px;gap:6px 10px;font-size:11px}.detail-pagination select{padding:4px}.detail-pagination div{width:100%;justify-content:flex-end;gap:10px}.detail-pagination button{padding:6px 9px;font-size:11px}.detail-footer{padding-top:8px;padding-bottom:8px;gap:6px}.detail-scroll{scroll-padding-top:45px}.view-actions span{display:none}}
</style>
